import{_ as e,C as t,c as r,o as n,j as i,b as l,a0 as s,a,w as o,G as k,a1 as d}from"./chunks/framework.DKRgXLPU.js";const g=JSON.parse('{"title":"Teknisk trening kontra flyttrening","description":"","frontmatter":{},"headers":[],"relativePath":"no/education/the-zone/technical-vs-flow.md","filePath":"no/education/the-zone/technical-vs-flow.md"}');const m=e({name:"no/education/the-zone/technical-vs-flow.md"},[["render",function(e,g,m,u,p,f){const h=t("Mermaid");return n(),r("div",null,[g[1]||(g[1]=i("h1",{id:"teknisk-trening-kontra-flyttrening",tabindex:"-1"},[a("Teknisk trening kontra flyttrening "),i("a",{class:"header-anchor",href:"#teknisk-trening-kontra-flyttrening","aria-label":'Permalink to "Teknisk trening kontra flyttrening"'},"​")],-1)),g[2]||(g[2]=i("p",null,"Det er viktig å forstå forskjellen mellom teknisk trening og flyttrening for eliteutvikling. Begge er nødvendige, men de tjener forskjellige formål og krever forskjellige tilnærminger.",-1)),g[3]||(g[3]=i("div",{class:"tip custom-block"},[i("p",{class:"custom-block-title"},"Kjerneprinsippet"),i("p",null,[i("strong",null,"Du kan ikke trene en nybegynner som en ekspert"),a(" (de mangler nevrale baner), og "),i("strong",null,"du kan ikke trene en ekspert som en nybegynner"),a(" (høyt teknisk volum forårsaker overtenking).")])],-1)),(n(),l(d,null,{default:o(()=>[k(h,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BNybegynner%20%3Cbr%2F%3E%2090%20%25%20teknologi%5D%20--%3E%20B%5BMiddels%20%3Cbr%2F%3E%2070%20%25%20teknologi%5D%0A%20%20%20%20B%20--%3E%20C%5BAvansert%20%3Cbr%2F%3E%2050%20%25%20teknologi%5D%0A%20%20%20%20C%20--%3E%20D%5BEkspert%20%3Cbr%2F%3E%2020%20%25%20teknologi%5D%0A%0A%20%20%20%20A2%5B10%20%25%20mental%5D%20--%3E%20B2%5B30%20%25%20mental%5D%0A%20%20%20%20B2%20--%3E%20C2%5B50%20%25%20mental%5D%0A%20%20%20%20C2%20--%3E%20D2%5B80%20%25%20mental%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffcdd2%0A%20%20%20%20style%20B%20fill%3A%23ffccbc%0A%20%20%20%20style%20C%20fill%3A%23fff9c4%0A%20%20%20%20style%20D%20fill%3A%23c8e6c9%0A%20%20%20%20style%20D2%20fill%3A%23a5d6a7%0A"})]),fallback:o(()=>[...g[0]||(g[0]=[a(" Loading... ",-1)])]),_:1})),g[4]||(g[4]=s('<h2 id="to-typer-trening" tabindex="-1">To typer trening <a class="header-anchor" href="#to-typer-trening" aria-label="Permalink to &quot;To typer trening&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Teknisk opplæring (eksplisitt læring)</p><p><strong>Fokus:</strong> Mekanikk og form <strong>Oppmerksomhet:</strong> Bevisste kroppsbevegelser <strong>Metode:</strong> Nedbryting av ferdigheter, repeterende øvelse <strong>Best for:</strong> Lære nye ferdigheter, korrigere dårlige vaner, bygge grunnlag</p><p><strong>Eksempel:</strong> Øv på utløsningspunktet ditt 50 ganger med videoanalyse</p></div><div class="info custom-block"><p class="custom-block-title">Flyttrening (implisitt læring)</p><p><strong>Fokus:</strong> Resultater, ikke mekanikk <strong>Oppmerksomhet:</strong> Å la underbevisstheten ta over <strong>Metode:</strong> Variert, spilllignende øvelse, visualisering <strong>Best for:</strong> Konkurranseforberedelse, bygge selvtillit, topp ytelse</p><p><strong>Eksempel:</strong> Å spille treningskamper med press, og kun fokusere på mål</p></div><h2 id="den-dynamiske-inversjonsmodellen" tabindex="-1">Den dynamiske inversjonsmodellen <a class="header-anchor" href="#den-dynamiske-inversjonsmodellen" aria-label="Permalink to &quot;Den dynamiske inversjonsmodellen&quot;">​</a></h2><p>Riktig treningsforhold er omvendt korrelert med teknisk kompetanse. Etter hvert som du mestrer teknikk, blir mental trening viktigere – ikke mindre.</p><h3 id="_1-nybegynner-kognitivt-stadium" tabindex="-1">1. Nybegynner (kognitivt stadium) <a class="header-anchor" href="#_1-nybegynner-kognitivt-stadium" aria-label="Permalink to &quot;1. Nybegynner (kognitivt stadium)&quot;">​</a></h3><ul><li>Du tenker bevisst på <em>hva</em> du skal gjøre</li><li>Bevegelsene føles vanskelige og krever innsats</li><li>Hjernen er fullstendig mettet med mekanikk</li><li><strong>Forhold:</strong> 90 % teknisk / 10 % mental</li><li><strong>Mentalt fokus:</strong> Nytelse, eksternt fokus (se på målet), ikke kompleks visualisering</li></ul><h3 id="_2-mellomstadiet-assosiativt-stadium" tabindex="-1">2. Mellomstadiet (assosiativt stadium) <a class="header-anchor" href="#_2-mellomstadiet-assosiativt-stadium" aria-label="Permalink to &quot;2. Mellomstadiet (assosiativt stadium)&quot;">​</a></h3><ul><li>Du foredler ferdigheten med mindre bevisst tankegang</li><li>Bevegelsene blir jevnere, feilene reduseres</li><li>Du begynner å oppdage dine egne feil</li><li><strong>Forhold:</strong> 70 % teknisk / 30 % mental</li><li><strong>Mental fokus:</strong> Utvikling av din pre-performance rutine (PPR)</li></ul><h3 id="_3-avansert-terskel-for-autonomi" tabindex="-1">3. Avansert (Terskel for autonomi) <a class="header-anchor" href="#_3-avansert-terskel-for-autonomi" aria-label="Permalink to &quot;3. Avansert (Terskel for autonomi)&quot;">​</a></h3><ul><li>Ferdigheten er i stor grad automatisert</li><li>Selvbildet ditt henger ofte etter din fysiske evne</li><li>Treningen fokuserer på trykksimulering</li><li><strong>Forhold:</strong> 50 % teknisk / 50 % mental</li><li><strong>Mental fokus:</strong> Visualisering, selvbilde, angstkontroll</li></ul><h3 id="_4-ekspert-autonom-fase" tabindex="-1">4. Ekspert (autonom fase) <a class="header-anchor" href="#_4-ekspert-autonom-fase" aria-label="Permalink to &quot;4. Ekspert (autonom fase)&quot;">​</a></h3><ul><li>Tekniske ferdigheter er fullstendig underbevisste</li><li>Bevisst oppmerksomhet på mekanikk forstyrrer ytelsen</li><li>Vedlikeholdsvolum er alt du trenger teknisk sett</li><li><strong>Forhold:</strong> 20 % teknisk / 80 % mental</li><li><strong>Mentalt fokus:</strong> Flyttilstand, strategi, roe ned sinnet</li></ul><h2 id="progresjonstabellen" tabindex="-1">Progresjonstabellen <a class="header-anchor" href="#progresjonstabellen" aria-label="Permalink to &quot;Progresjonstabellen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nivå</th><th>Teknologi: Mental</th><th>Hovedmål</th></tr></thead><tbody><tr><td>Nybegynner</td><td>90 : 10</td><td>Bygg maskinen</td></tr><tr><td>Middels</td><td>70:30</td><td>Stabiliser ferdigheten</td></tr><tr><td>Avansert</td><td>50:50</td><td>Stol på maskinen</td></tr><tr><td>Ekspert</td><td>20:80</td><td>Frihet til å yte</td></tr></tbody></table><h2 id="ekspertfellen" tabindex="-1">Ekspertfellen <a class="header-anchor" href="#ekspertfellen" aria-label="Permalink to &quot;Ekspertfellen&quot;">​</a></h2><p>For avanserte og ekspertspillere er det farlig å gå tilbake til høyt teknisk fokus.</p><p><strong>Problemet:</strong> Når du har automatisert en ferdighet, men bevisst overvåker den under konkurranse, engasjerer du det bevisste sinnet og overstyrer det underbevisste. Dette forårsaker prestasjonsangst og «kvelningsangst».</p><p><strong>Vitenskapen:</strong> Volumet som kreves for å opprettholde en ferdighet er betydelig lavere (ofte 1/3 til 1/9) enn volumet som kreves for å bygge den opp. Eksperter trenger minimalt med teknisk arbeid for å beholde touchet.</p><p><strong>Eliteeksempel:</strong> Mestere som Philippe Quintais og Dylan Rocher fokuserer sterkt på taktiske scenarier og kritiske øyeblikk i stedet for mekaniske øvelser.</p><p>Tegn på at du tenker for mye på teknikk:</p><ul><li>Lammelse ved analyse</li><li>Inkonsekvent prestasjon til tross for god teknikk</li><li>Dårligere resultater i konkurranse enn i trening</li><li>Føler seg «mekanisk» i stedet for flytende</li></ul><h2 id="sammenligning-av-treningsmetoder" tabindex="-1">Sammenligning av treningsmetoder <a class="header-anchor" href="#sammenligning-av-treningsmetoder" aria-label="Permalink to &quot;Sammenligning av treningsmetoder&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspekt</th><th>Teknisk opplæring</th><th>Flyttrening</th></tr></thead><tbody><tr><td><strong>Øvingstype</strong></td><td>Blokkert (samme ferdighet gjentatte ganger)</td><td>Tilfeldig (varierte ferdigheter)</td></tr><tr><td><strong>Tilbakemelding</strong></td><td>Umiddelbar, detaljert</td><td>Forsinket, resultatfokusert</td></tr><tr><td><strong>Miljø</strong></td><td>Kontrollert, forutsigbar</td><td>Variabel, spilllignende</td></tr><tr><td><strong>Mental tilstand</strong></td><td>Analytisk, bevisst</td><td>Intuitiv, automatisk</td></tr><tr><td><strong>Beste tid</strong></td><td>Ferdighetsbygging utenom sesongen</td><td>Før konkurranse, vedlikehold</td></tr></tbody></table><h2 id="blokkert-vs-tilfeldig-øvelse" tabindex="-1">Blokkert vs. tilfeldig øvelse <a class="header-anchor" href="#blokkert-vs-tilfeldig-øvelse" aria-label="Permalink to &quot;Blokkert vs. tilfeldig øvelse&quot;">​</a></h2><p><strong>Blokkert øvelse:</strong> Gjenta samme kast 20 ganger</p><ul><li>Føles produktiv (du ser rask forbedring)</li><li>Bra for innledende læring</li><li>Dårlig for langsiktig oppbevaring</li></ul><p><strong>Tilfeldig øvelse:</strong> Varier avstand, mål og kastetype</p><ul><li>Føles vanskeligere (flere feil)</li><li>Bedre for konkurranseoverføring</li><li>Bygger tilpasningsevne og beslutningstaking</li></ul><h2 id="praktiske-retningslinjer" tabindex="-1">Praktiske retningslinjer <a class="header-anchor" href="#praktiske-retningslinjer" aria-label="Permalink to &quot;Praktiske retningslinjer&quot;">​</a></h2><h3 id="for-tekniske-økter" tabindex="-1">For tekniske økter <a class="header-anchor" href="#for-tekniske-økter" aria-label="Permalink to &quot;For tekniske økter&quot;">​</a></h3><ol><li>Fokuser på ETT aspekt om gangen</li><li>Bruk videoanalyse</li><li>Få tilbakemeldinger fra en trener eller treningspartner</li><li>Aksepter at det vil føles litt rart i starten</li><li>Hold øktene kortere (kvalitet fremfor kvantitet)</li></ol><h3 id="for-flytøkter" tabindex="-1">For flytøkter <a class="header-anchor" href="#for-flytøkter" aria-label="Permalink to &quot;For flytøkter&quot;">​</a></h3><ol><li>Skap et spilllignende press</li><li>Fokuser på målet, ikke kroppen din</li><li>Bruk rutinen din før bruk konsekvent</li><li>Ikke analyser under økten</li><li>Stol på treningen din</li></ol><h2 id="integrasjonsutfordringen" tabindex="-1">Integrasjonsutfordringen <a class="header-anchor" href="#integrasjonsutfordringen" aria-label="Permalink to &quot;Integrasjonsutfordringen&quot;">​</a></h2><p>Den virkelige ferdigheten er å vite når man skal bruke hver modus:</p><p><strong>Under en konkurransekamp:</strong></p><ul><li>Teknisk tenkning: ALDRI under utførelse</li><li>Flytmodus: ALLTID når du kaster</li></ul><p><strong>Under trening:</strong></p><ul><li>Tekniske økter: Planlagt, spesifikt fokus</li><li>Flytøkter: Spillsimulering, trykkøvelse</li></ul><h2 id="eksempel-pa-ukentlig-saldo" tabindex="-1">Eksempel på ukentlig saldo <a class="header-anchor" href="#eksempel-pa-ukentlig-saldo" aria-label="Permalink to &quot;Eksempel på ukentlig saldo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dag</th><th>Økttype</th><th>Fokus</th></tr></thead><tbody><tr><td>mandag</td><td>Teknisk</td><td>Pekepresisjon</td></tr><tr><td>tirsdag</td><td>Teknisk</td><td>Skytingsnøyaktighet</td></tr><tr><td>onsdag</td><td>Strømme</td><td>Mental trening, visualisering</td></tr><tr><td>torsdag</td><td>Blandet</td><td>Spillscenarier med flytfokus</td></tr><tr><td>fredag</td><td>Teknisk</td><td>Svakhetsområde</td></tr><tr><td>lørdag</td><td>Strømme</td><td>Kampspill, konkurransesimulering</td></tr><tr><td>søndag</td><td>Hvile</td><td>Gjenoppretting, refleksjon</td></tr></tbody></table><h2 id="sammendrag-regler-for-treningsbalanse" tabindex="-1">Sammendrag: Regler for treningsbalanse <a class="header-anchor" href="#sammendrag-regler-for-treningsbalanse" aria-label="Permalink to &quot;Sammendrag: Regler for treningsbalanse&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Regel nr. 1: Tilpass trening til nivå</p><p><strong>Nybegynnere (90/10):</strong> Bygg maskinen – fokuser på teknikk <strong>Middels (70/30):</strong> Stabiliser ferdigheten – legg til mentalt arbeid <strong>Avansert (50/50):</strong> Stol på maskinen – balanser begge deler <strong>Ekspert (20/80):</strong> Prestasjonsfrihet – hovedsakelig mental</p></div><div class="tip custom-block"><p class="custom-block-title">Regel nr. 2: Blokkert vs. tilfeldig øvelse</p><p><strong>Blokkert øvelse</strong> (samme kast gjentatte ganger): Bra for innledende læring, dårlig for vedvaring <strong>Tilfeldig øvelse</strong> (varierte kast): Vanskeligere på øvelse, bedre i konkurranse</p></div><div class="tip custom-block"><p class="custom-block-title">Regel nr. 3: Ekspertfellen</p><p><strong>For eksperter:</strong> Høyt teknisk volum forårsaker overtenking og kvelning <strong>Løsning:</strong> Minimalt teknisk vedlikehold, maksimal mental trening</p></div><h2 id="viktig-konklusjon" tabindex="-1">Viktig konklusjon <a class="header-anchor" href="#viktig-konklusjon" aria-label="Permalink to &quot;Viktig konklusjon&quot;">​</a></h2><blockquote><p>Du kan ikke trene en nybegynner som en ekspert (de mangler nevrale baner for mentalt arbeid), og du kan ikke trene en ekspert som en nybegynner (høyt teknisk volum forårsaker utbrenthet og overtenking).</p></blockquote><p>Reisen fra teknikk til flyt krever strategisk inversjon. Tilpass treningen din til utviklingsstadiet ditt.</p>',49))])}]]);export{g as __pageData,m as default};
